<script setup lang="ts">
import { checkStatuses, type InspectionCheck, type InspectionReport } from '../coordination';
defineProps<{checklist:InspectionCheck[];readonly?:boolean}>();
const report=defineModel<InspectionReport>({required:true});
const fields=[['enterprises','排查企业数'],['vehicles','排查车辆数'],['problemVehicles','问题车辆数'],['rectifiedVehicles','已整改车辆数']] as const;
</script>
<template><section class="coord-inspection-report"><div class="coord-report-numbers"><div v-for="[key,name] in fields" :key="key"><span>{{name}}</span><strong v-if="readonly">{{report[key]}}</strong><el-input-number v-else v-model="report[key]" :min="0" :max="1000000" :precision="0" controls-position="right" :aria-label="name"/></div></div><div class="coord-check-results"><div v-for="(item,index) in checklist" :key="item.id" class="coord-check-result"><div class="coord-check-result-title"><span>{{index+1}}. {{item.label}}</span><el-tag v-if="readonly" :type="report.checks.find(row=>row.itemId===item.id)?.status==='ISSUE'?'warning':report.checks.find(row=>row.itemId===item.id)?.status==='NORMAL'?'success':'info'" effect="plain">{{checkStatuses[report.checks.find(row=>row.itemId===item.id)?.status||'']||'未填报'}}</el-tag><el-select v-else-if="report.checks[index]" v-model="report.checks[index]!.status" :aria-label="`检查结果${index+1}`" placeholder="选择检查结果"><el-option v-for="(name,key) in checkStatuses" :key="key" :label="name" :value="key"/></el-select></div><p v-if="readonly&&report.checks.find(row=>row.itemId===item.id)?.note" class="coord-prose">{{report.checks.find(row=>row.itemId===item.id)?.note}}</p><el-input v-else-if="!readonly&&report.checks[index]" v-model="report.checks[index]!.note" :aria-label="`检查说明${index+1}`" type="textarea" :rows="2" maxlength="1000" :placeholder="report.checks[index]!.status==='NORMAL'?'补充说明（选填）':'说明发现的问题、整改措施或不适用原因'"/></div></div></section></template>
